pub fn largest_power_of_two_le(n: i8) -> i8 {
    // Assumption: n >= 1
    let mut z: i8 = 1;

    // Only considers powers of two: z is always 1,2,4,8,...
    // Maintains z in [1, n] by only doubling when 2*z <= n.
    while z <= n / 2 {
        z *= 2;
    }
    z
}

pub fn solve(n: i8) -> i8 {
    // Assumption: n >= 1
    if (n & 1) != 0 {
        // n is odd
        (n - 1) / 2
    } else {
        // n is even
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}